mapper.select:
SELECT * FROM (
    SELECT * FROM ALIPAY_SIGN_INFO
    WHERE DELETE_FLAG = '0'
      AND CHANNEL_SYNC_STATUS != 'SUCCESS'
      AND NVL(CHANNEL_SYNC_RETRY_COUNT, 0) < #{maxRetryCount,jdbcType=INTEGER}
      AND (CHANNEL_SYNC_RESULT IS NULL OR CHANNEL_SYNC_RESULT NOT LIKE 'BIZ_REJECTED:%')
    ORDER BY NVL(CHANNEL_SYNC_TIME, CREATE_TIME)
) WHERE ROWNUM <= #{batchSize,jdbcType=INTEGER}
